presets.css:
/* ========== A. 主题变量 (Ins 韩系极简灰粉) ========== */
.chat-thread {
  /* 背景：温柔奶灰色铺底 */
  --dress-chat-bg-overlay: #F7F5F6;

  /* 顶栏：粉色长方形连接顶部 */
  --dress-header-bg: rgba(242, 227, 232, 0.95);
  --dress-header-blur: 20px;
  --dress-header-border: 1px solid rgba(255, 255, 255, 0.6);
  --dress-header-radius: 0 0 28px 28px; /* 顶部平直连接，底部圆润 */
  --dress-header-shadow: 0 8px 24px rgba(200, 180, 185, 0.15);
  --dress-header-title-color: #6B6064;
  --dress-header-title-size: 14px;
  --dress-header-title-weight: 600;
  --dress-header-icon-color: #8C7F84;

  /* 我方气泡：灰粉色，呼应顶栏底栏 */
  --dress-bubble-me-bg: #F2E3E8;
  --dress-bubble-me-fg: #5A5054;
  --dress-bubble-me-border: 1px solid rgba(255, 255, 255, 0.8);
  --dress-bubble-me-shadow: 0 4px 16px rgba(200, 180, 185, 0.2);
  /* 我方气泡：左上、左下、右下圆润，右上角(靠近头像)变小，形成水滴感 */
  --dress-bubble-me-radius: 20px 4px 20px 20px;

  /* 对方气泡：奶灰色，呼应输入框和名字底色 */
  --dress-bubble-them-bg: #ECECEE;
  --dress-bubble-them-fg: #5A5054;
  --dress-bubble-them-border: 1px solid rgba(255, 255, 255, 0.9);
  --dress-bubble-them-shadow: 0 4px 16px rgba(0, 0, 0, 0.03);
  /* 对方气泡：右上、右下、左下圆润，左上角(靠近头像)变小 */
  --dress-bubble-them-radius: 4px 20px 20px 20px;

  /* 输入胶囊外层 (底栏整体粉色) */
  --dress-compose-bar-bg: rgba(242, 227, 232, 0.95);
  --dress-compose-bar-fg: #6B6064;
  --dress-compose-bar-radius: 28px 28px 0 0; /* 底部平直连接，顶部圆润 */
  --dress-compose-bar-border: 1px solid rgba(255, 255, 255, 0.6);
  --dress-compose-bar-shadow: 0 -8px 24px rgba(200, 180, 185, 0.15);
  --dress-compose-bar-blur: blur(20px);

  --dress-timestamp-color: #A89FA3;
  --dress-scroll-pad-x: 16px;
}

/* 深色模式：高级灰紫调 */
html[data-theme="dark"] .chat-thread {
  --dress-chat-bg-overlay: #2A2628;
  --dress-header-bg: rgba(62, 53, 56, 0.95);
  --dress-header-title-color: #E6E0E2;
  --dress-header-icon-color: #B5ADB0;
  --dress-bubble-me-bg: #52474A;
  --dress-bubble-me-fg: #F0EBEB;
  --dress-bubble-me-border: 1px solid rgba(255, 255, 255, 0.05);
  --dress-bubble-them-bg: #383435;
  --dress-bubble-them-fg: #E6E0E2;
  --dress-bubble-them-border: 1px solid rgba(255, 255, 255, 0.05);
  --dress-compose-bar-bg: rgba(62, 53, 56, 0.95);
}

/* ========== B. 壳 / 滚动 / 白色波点背景 ========== */
.chat-thread {
  background-color: var(--dress-chat-bg-overlay);
  /* 白色高雅波点点缀 */
  background-image: radial-gradient(#FFFFFF 1.5px, transparent 1.5px);
  background-size: 24px 24px;
}

html[data-theme="dark"] .chat-thread {
  background-image: radial-gradient(rgba(255,255,255,0.05) 1.5px, transparent 1.5px);
}

/* ========== C. 顶栏重构 (彻底贴顶长方形 + 灰色名字区 + 白色翅膀) ========== */
/* 强制消除某些系统默认的顶栏外容器间距 */
.chat-thread-header {
  margin: 0 !important;
  padding: 0 !important;
  width: 100% !important;
}

.chat-thread-pill {
  /* 强制覆盖原有的胶囊外边距，确保不悬浮、贴合顶部屏幕边缘 */
  margin: 0 !important;
  top: 0 !important;
  width: 100% !important;
  max-width: 100% !important;
  border-radius: var(--dress-header-radius) !important;
  padding-top: max(env(safe-area-inset-top, 16px), 16px) !important;
  box-shadow: var(--dress-header-shadow);
}

/* 中间名字区域：灰色背景填充，呼应对方气泡 */
.chat-thread-center h2 {
  background: var(--dress-bubble-them-bg);
  padding: 4px 18px;
  border-radius: 20px;
  box-shadow: inset 0 2px 4px rgba(255, 255, 255, 0.8), 0 2px 8px rgba(0,0,0,0.02);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

/* 名字两侧加入白色翅膀点缀 (Ins风颜文字) */
.chat-thread-center h2::before {
  content: "ʚ";
  color: #FFF;
  font-size: 16px;
  text-shadow: 0 1px 2px rgba(0,0,0,0.1);
  font-weight: normal;
}
.chat-thread-center h2::after {
  content: "ɞ";
  color: #FFF;
  font-size: 16px;
  text-shadow: 0 1px 2px rgba(0,0,0,0.1);
  font-weight: normal;
}

/* ========== D. 消息 / 气泡样式 ========== */
.chat-bubble {
  /* 缩减上下左右的内边距，让气泡更修长紧凑 */
  padding: 8px 14px !important; 
  line-height: 1.5;
  font-size: 14px; /* 字号控制在秀气的范围 */
}

/* ========== E. 头像框白边设计 ========== */
.chat-ava, .chat-ava-sm {
  border: 2px solid #FFFFFF !important;
  border-radius: 50% !important; /* 强制正圆 */
  box-shadow: 0 3px 8px rgba(200, 180, 185, 0.4) !important;
  position: relative;
  /* 去除挂件后可以改回 hidden，让头像图片不会溢出边框 */
  overflow: hidden !important; 
}

/* 确保头像内的图片配合外框 */
.chat-ava img, .chat-ava-sm img {
  border-radius: 50% !important;
  width: 100%; 
  height: 100%;
  object-fit: cover;
}

/* ========== F. 输入区重构 (贴底粉色长方形 + 灰色输入框 + 白色兔子) ========== */
.chat-compose-bar {
  margin: 0 !important;
  width: 100% !important;
  max-width: 100% !important;
  border-radius: var(--dress-compose-bar-radius) !important;
  padding: 14px 16px max(env(safe-area-inset-bottom, 16px), 16px) !important;
  position: relative;
}

/* 悬浮的白色兔子点缀，趴在底栏上方 */
.chat-compose-bar::before {
  content: "ᕱ⑅ᕱ";
  position: absolute;
  top: -26px;
  right: 28px;
  font-size: 18px;
  color: #FFFFFF;
  text-shadow: 0 2px 6px rgba(200, 180, 185, 0.4);
  letter-spacing: -2px;
  animation: bunnyFloat 4s ease-in-out infinite;
  z-index: 10;
}

@keyframes bunnyFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-4px); }
}

/* 输入框本体：奶灰色填充，呼应对方气泡 */
.chat-compose-input {
  background: var(--dress-bubble-them-bg) !important;
  border-radius: 999px !important; /* 彻底圆角 */
  border: 1px solid rgba(255, 255, 255, 0.8);
  box-shadow: inset 0 2px 6px rgba(0,0,0,0.02);
  padding: 10px 18px !important;
}

/* 图标颜色微调，融入整体灰粉调 */
.chat-compose-icon {
  color: #8C7F84;
}
/* ========== 1. 高级感云朵/饼干边缘 (舒展波浪 + 边缘对齐修复) ========== */
.chat-thread {
  --dress-bubble-me-border: none;
  --dress-bubble-them-border: none;
  --dress-bubble-me-shadow: none; 
  --dress-bubble-them-shadow: none;
  --dress-bubble-me-radius: 12px;
  --dress-bubble-them-radius: 12px;
}

.chat-bubble {
  /* 1. 扩大透明边框，给更舒展的大波浪留出空间 */
  border: 6px solid transparent !important;
  padding: 6px 14px !important; 
  line-height: 1.5;
  font-size: 14px;

  filter: drop-shadow(0 2px 5px rgba(200, 180, 185, 0.3));

  /* 2. 拆分 Mask 属性写法，放大圆点并修复边缘截断问题 */
  -webkit-mask-image: linear-gradient(#fff 0 0), radial-gradient(circle at 7px 7px, #fff 6px, transparent 7px);
  -webkit-mask-origin: padding-box, border-box;
  -webkit-mask-clip: padding-box, border-box;
  /* 将波浪尺寸从 8px 放大到 14px，大幅降低密集度 */
  -webkit-mask-size: auto, 14px 14px;
  /* 核心修复：使用 round 属性！它会让波浪自动拉伸凑整，保证右边缘完美闭合，不再出现半个圆 */
  -webkit-mask-repeat: no-repeat, round;

  /* 标准属性兼容 */
  mask-image: linear-gradient(#fff 0 0), radial-gradient(circle at 7px 7px, #fff 6px, transparent 7px);
  mask-origin: padding-box, border-box;
  mask-clip: padding-box, border-box;
  mask-size: auto, 14px 14px;
  mask-repeat: no-repeat, round;

  -webkit-mask-composite: source-over;
  mask-composite: add;
}
